node -e '
const exp=require("./tests/expected.json");
const A=v=>(v+Math.floor(v/3))%997;
const B=(v,N)=>v^((N*7)%64);
const C=(v,N)=>(v*3-N)%991;
const D=v=>(v*2+1)%1000;
let v=exp.input, ok=true;
for(let n=1;n<=32;n++){
  const t=(n-1)%4;
  v = t===0?A(v): t===1?B(v,n): t===2?C(v,n): D(v);
  if(v!==exp.stages[n-1]){console.log("FAIL at",n,v,"want",exp.stages[n-1]);ok=false;}
}
console.log(ok?"ALL 32 GREEN":"see above");'

